import sys

def is_palindrome(s):
    return s == s[::-1]

def count_palindromic_shifts(s):
    n = len(s)
    count = 0
    for k in range(n):
        shifted = s[k:] + s[:k]
        if is_palindrome(shifted):
            count += 1
    return count

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        S = data[index]
        index += 1
        results.append(count_palindromic_shifts(S))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
